_EMBEDDED_SOURCES = {'remail': '# noplug\n"""Remail pickup API, using the contract supplied from /docs.\n\nNo dependency on Cardinal. Tokens, messages and credentials are never logged.\n"""\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom email.utils import parseaddr, parsedate_to_datetime\nfrom html import unescape\nfrom html.parser import HTMLParser\nimport json\nimport math\nimport re\nimport time\nfrom urllib.error import HTTPError, URLError\nfrom urllib.parse import parse_qs, urlencode, urlsplit\nfrom urllib.request import HTTPRedirectHandler, Request, build_opener\n\nBASE_URL = \'https://remail.aishop6.com\'\nPICKUP_HOSTS = frozenset((\'remail.aishop6.com\', \'remail.best\'))\n\n\nclass MailError(Exception):\n    """Safe to display: never includes an HTTP URL or response body."""\n    def __init__(self, message, *, retryable=False, retry_after=0, code=\'mail_error\'):\n        super().__init__(message)\n        self.retryable = retryable\n        self.retry_after = retry_after\n        self.code = code\n\n\n@dataclass(frozen=True, repr=False)\nclass Credentials:\n    email: str\n    token: str\n    base_url: str = BASE_URL\n\n    def pickup_url(self):\n        return self.base_url + \'/pickup?\' + urlencode({\'email\': self.email, \'token\': self.token})\n\n\ndef normalize_pickup(value):\n    if not isinstance(value, str):\n        raise MailError(\'Paste one complete Remail link\', code=\'pickup_format\')\n    value = value.strip()\n    # Accept a single Markdown link copied from chat, without evaluating its label.\n    markdown = re.fullmatch(r\'\\[[^\\[\\]\\r\\n]*\\]\\((https://[^\\s]+)\\)\', value)\n    if markdown:\n        value = markdown.group(1)\n    if value.startswith(\'<\') and value.endswith(\'>\'):\n        value = value[1:-1]\n    value = value.replace(\'\\\\&\', \'&\').replace(\'&amp;\', \'&\')\n    if not value or any(c.isspace() or ord(c) < 32 for c in value):\n        raise MailError(\'Paste one complete Remail link\', code=\'pickup_format\')\n    return value\n\n\ndef credentials(email, pickup):\n    pickup = normalize_pickup(pickup)\n    try:\n        u = urlsplit(pickup)\n        q = parse_qs(u.query, keep_blank_values=True)\n        valid = (u.scheme == \'https\' and u.port in (None, 443)\n                 and not u.username and not u.password and u.path == \'/pickup\' and not u.fragment)\n    except (ValueError, TypeError):\n        valid = False\n    if not valid:\n        raise MailError(\'Expected an HTTPS Remail /pickup link\', code=\'pickup_format\')\n    if u.hostname not in PICKUP_HOSTS:\n        raise MailError(\'Unsupported Remail domain\', code=\'pickup_host\')\n    if q.get(\'email\') != [email] or not isinstance(email, str) or \'@\' not in email:\n        raise MailError(\'Account email does not match the link\', code=\'pickup_email\')\n    if len(q.get(\'token\', [])) != 1 or not q[\'token\'][0]:\n        raise MailError(\'Link must contain one nonempty token\', code=\'pickup_token\')\n    return Credentials(email, q[\'token\'][0], \'https://\' + u.hostname)\n\n\ndef timestamp(value):\n    try:\n        dt = datetime.fromisoformat(value.replace(\'Z\', \'+00:00\'))\n        return dt.timestamp() if dt.tzinfo else None\n    except (ValueError, TypeError, AttributeError, OverflowError):\n        return None\n\n\ndef login_value(value):\n    if not isinstance(value, str):\n        raise MailError(\'Invalid login credential\')\n    if re.fullmatch(r\'[0-9]{4,12}\', value):\n        return value\n    try:\n        u = urlsplit(value)\n        if (u.scheme == \'https\' and u.hostname == \'claude.ai\' and not u.username\n                and not u.password and u.port in (None, 443) and u.path not in (\'\', \'/\')\n                and u.query and not any(c.isspace() or ord(c) < 32 for c in value)):\n            return value\n    except ValueError:\n        pass\n    raise MailError(\'Expected a numeric code or an HTTPS Claude login link\')\n\n\nclass _Links(HTMLParser):\n    def __init__(self):\n        super().__init__()\n        self.values = []\n\n    def handle_starttag(self, tag, attrs):\n        if tag == \'a\':\n            self.values.extend(v for k, v in attrs if k == \'href\' and v)\n\n\ndef extract_login(message):\n    code = message.get(\'verificationCode\')\n    if isinstance(code, str) and re.fullmatch(r\'[0-9]{4,12}\', code.strip()):\n        return code.strip()\n    body = message.get(\'body\') or message.get(\'bodyPreview\') or \'\'\n    if not isinstance(body, str):\n        raise MailError(\'Invalid message body\')\n    links = _Links()\n    links.feed(body)\n    candidates = links.values + re.findall(r\'https://[^\\s<>"\\\']+\', unescape(body))\n    found = set()\n    for candidate in candidates:\n        try:\n            found.add(login_value(candidate))\n        except MailError:\n            continue\n    if len(found) != 1:\n        raise MailError(\'No unambiguous Claude login link or verification code in message\')\n    return found.pop()\n\n\nclass _NoRedirects(HTTPRedirectHandler):\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        return None  # A query token must never follow an unexpected redirect.\n\n\nclass Client:\n    def __init__(self, account, *, opener=None):\n        self.auth = credentials(account[\'email\'], account[\'pickup\'])\n        # Standard TLS verification and inherited proxy/CA configuration remain enabled.\n        self.opener = opener or build_opener(_NoRedirects())\n\n    def _get(self, path, timeout=15):\n        query = urlencode({\'email\': self.auth.email, \'token\': self.auth.token})\n        req = Request(f\'{self.auth.base_url}{path}?{query}\', headers={\'Accept\': \'application/json\'})\n        try:\n            with self.opener.open(req, timeout=timeout) as response:\n                raw = response.read(2 * 1024 * 1024 + 1)\n            if len(raw) > 2 * 1024 * 1024:\n                raise MailError(\'Remail response exceeded size limit\')\n            result = json.loads(raw)\n            if not isinstance(result, dict):\n                raise MailError(\'Unexpected Remail response schema\')\n            return result\n        except HTTPError as exc:\n            delay = 0\n            retry = exc.headers.get(\'Retry-After\', \'\') if exc.headers else \'\'\n            try:\n                delay = float(retry)\n            except ValueError:\n                try:\n                    delay = parsedate_to_datetime(retry).timestamp() - time.time()\n                except (ValueError, TypeError, OverflowError):\n                    pass\n            if not math.isfinite(delay):\n                delay = 0\n            status = exc.code\n            exc.close()\n            raise MailError(f\'Remail HTTP {status}\', retryable=status in (429, 500, 502, 503, 504),\n                            retry_after=max(0, delay)) from None\n        except (URLError, OSError, ValueError):\n            raise MailError(\'Remail transport or JSON error\', retryable=True) from None\n\n    def pickup(self, timeout=15):\n        result = self._get(\'/v1/pickup\', timeout)\n        items = result.get(\'items\')\n        fetch = result.get(\'fetch\')\n        if (not isinstance(items, list) or not isinstance(fetch, dict)\n                or any(not isinstance(m, dict) or type(m.get(\'id\')) is not int or m[\'id\'] <= 0\n                       for m in items)):\n            raise MailError(\'Unexpected Remail pickup schema\')\n        return items, fetch\n\n    def message(self, message_id, timeout=15):\n        if type(message_id) is not int or message_id <= 0:\n            raise MailError(\'Invalid message ID\')\n        return self._get(f\'/v1/pickup/messages/{message_id}\', timeout)\n\n\n@dataclass(frozen=True)\nclass Snapshot:\n    ids: frozenset\n    since: float\n    next_fetch: float\n\n\nclass Mailbox:\n    def __init__(self, client, allowed_senders, *, poll_seconds=5,\n                 clock=time.time, monotonic=time.monotonic, sleep=time.sleep):\n        self.client = client\n        self.senders = frozenset(s.casefold() for s in allowed_senders)\n        if not self.senders or any(\'@\' not in s for s in self.senders):\n            raise MailError(\'Configure exact trusted Claude sender addresses before issuing codes\')\n        self.poll_seconds = max(1, float(poll_seconds))\n        self.clock, self.monotonic, self.sleep = clock, monotonic, sleep\n\n    def snapshot(self):\n        items, fetch = self.client.pickup()\n        return Snapshot(frozenset(m[\'id\'] for m in items), self.clock(),\n                        timestamp(fetch.get(\'nextFetchAllowedAt\')) or 0)\n\n    def _matches(self, message, snapshot):\n        received = timestamp(message.get(\'receivedAt\'))\n        sender = parseaddr(str(message.get(\'sender\', \'\')))[1].casefold()\n        recipient = parseaddr(str(message.get(\'recipient\', \'\')))[1]\n        return (message.get(\'id\') not in snapshot.ids and received is not None\n                and snapshot.since <= received <= self.clock()\n                and sender in self.senders and recipient == self.client.auth.email)\n\n    def wait(self, snapshot, timeout=120):\n        if not 0 < timeout <= 600:\n            raise MailError(\'Mail wait timeout must be between 0 and 600 seconds\')\n        deadline = self.monotonic() + timeout\n        next_poll = snapshot.next_fetch\n        while self.monotonic() < deadline:\n            delay = max(0, next_poll - self.clock())\n            self.sleep(min(delay, max(0, deadline - self.monotonic())))\n            remaining = deadline - self.monotonic()\n            if remaining <= 0:\n                break\n            try:\n                items, fetch = self.client.pickup(timeout=min(15, remaining))\n                next_poll = max(self.clock() + self.poll_seconds,\n                                timestamp(fetch.get(\'nextFetchAllowedAt\')) or 0)\n                matching = [m for m in items if self._matches(m, snapshot)]\n                # Multiple login attempts cannot be correlated to one buyer: fail closed.\n                if len(matching) > 1:\n                    raise MailError(\'Multiple fresh messages; operator review required\')\n                if matching:\n                    m = matching[0]\n                    remaining = deadline - self.monotonic()\n                    if remaining <= 0:\n                        break\n                    detail = self.client.message(m[\'id\'], timeout=min(15, remaining))\n                    if detail.get(\'id\') != m[\'id\'] or not self._matches(detail, snapshot):\n                        raise MailError(\'Message details do not match the requested mailbox\')\n                    if self.monotonic() >= deadline:\n                        break\n                    return {\'value\': extract_login(detail), \'message_id\': m[\'id\']}\n            except MailError as exc:\n                if not exc.retryable:\n                    raise\n                next_poll = max(next_poll, self.clock() + max(self.poll_seconds, exc.retry_after))\n        raise MailError(\'Timed out waiting for a fresh login email\')\n\n\nclass Provider:\n    """Compose the mail client with an independently validated Claude adapter."""\n    def __init__(self, claude, settings, client_factory=Client):\n        self.claude, self.settings, self.client_factory = claude, settings, client_factory\n\n    def usage(self, account):\n        return self.claude.usage(account)\n\n    def revoke_all(self, rental):\n        return self.claude.revoke_all(rental)\n\n    def issue(self, account, order_id):\n        mailbox = Mailbox(self.client_factory(account), self.settings[\'allowed_senders\'],\n                          poll_seconds=self.settings.get(\'poll_seconds\', 5))\n        snapshot = mailbox.snapshot()\n        # Caller exclusively reserves the account before this method; never retry login here.\n        self.claude.request_login(account, order_id)\n        return mailbox.wait(snapshot, self.settings.get(\'timeout_seconds\', 120))\n\n\ndef main():\n    import argparse\n    from rental import Store\n    p = argparse.ArgumentParser(description=\'Check Remail access without exposing codes or tokens\')\n    p.add_argument(\'--db\', default=\'data/rentals.sqlite3\')\n    p.add_argument(\'--account-id\', type=int, required=True)\n    p.add_argument(\'--show-senders\', action=\'store_true\', help=\'List sender addresses, without mail bodies or codes\')\n    args = p.parse_args()\n    account = next((a for a in Store(args.db).accounts() if a[\'id\'] == args.account_id), None)\n    if account is None:\n        p.exit(1, \'Account not found\\n\')\n    try:\n        items, _ = Client(account).pickup()\n    except MailError as exc:\n        p.exit(1, f\'{exc}\\n\')\n    print(f\'Remail API доступен. Писем в ответе: {len(items)}. Коды и содержимое скрыты.\')\n    if args.show_senders:\n        senders = sorted({parseaddr(str(m.get(\'sender\', \'\')))[1] for m in items})\n        print(json.dumps({\'senders\': senders}, ensure_ascii=True))\n\n\nif __name__ == \'__main__\':\n    main()\n', 'rental': '# noplug\n"""Durable exclusive rentals. Provider operations must be idempotent by order ID."""\nimport argparse\nfrom contextlib import contextmanager\nimport hashlib\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport sqlite3\nimport time\nfrom datetime import datetime, timedelta, timezone\nfrom remail import credentials, login_value\n\n\nclass Unavailable(Exception):\n    pass\n\n\ndef format_duration(seconds):\n    hours, rest = divmod(seconds, 3600)\n    minutes, seconds = divmod(rest, 60)\n    return \' \'.join(f\'{v} {unit}\' for v, unit in ((hours, \'ч\'), (minutes, \'мин\'), (seconds, \'сек\')) if v)\n\n\ndef end_time(timestamp):\n    return datetime.fromtimestamp(timestamp, timezone(timedelta(hours=3))).strftime(\'%d.%m %H:%M МСК\')\n\n\nclass Store:\n    def __init__(self, path):\n        self.path = str(path)\n        Path(path).parent.mkdir(parents=True, exist_ok=True, mode=0o700)\n        fd = os.open(self.path, os.O_CREAT | os.O_RDWR, 0o600)\n        os.close(fd)\n        os.chmod(self.path, 0o600)\n        with self.db() as c:\n            c.executescript(\'\'\'\n                CREATE TABLE IF NOT EXISTS accounts (\n                    id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL,\n                    pickup TEXT NOT NULL, state TEXT NOT NULL DEFAULT \'quarantine\',\n                    five REAL, seven REAL, checked REAL);\n                CREATE TABLE IF NOT EXISTS rentals (\n                    order_id TEXT PRIMARY KEY, buyer TEXT NOT NULL, chat TEXT NOT NULL,\n                    account_id INTEGER NOT NULL REFERENCES accounts(id),\n                    seconds INTEGER NOT NULL, state TEXT NOT NULL,\n                    expires REAL NOT NULL, code_hash TEXT UNIQUE,\n                    FOREIGN KEY(account_id) REFERENCES accounts(id));\n                CREATE UNIQUE INDEX IF NOT EXISTS exclusive_account\n                    ON rentals(account_id) WHERE state != \'closed\';\n                CREATE TABLE IF NOT EXISTS mail_claims (\n                    account_id INTEGER NOT NULL REFERENCES accounts(id),\n                    message_id INTEGER NOT NULL,\n                    order_id TEXT NOT NULL UNIQUE REFERENCES rentals(order_id),\n                    PRIMARY KEY(account_id, message_id));\n                CREATE TABLE IF NOT EXISTS purchases (\n                    order_id TEXT PRIMARY KEY, buyer TEXT NOT NULL, chat TEXT NOT NULL,\n                    seconds INTEGER NOT NULL, kind TEXT NOT NULL DEFAULT \'pending\',\n                    rental_id TEXT REFERENCES rentals(order_id), created REAL NOT NULL);\n                CREATE TABLE IF NOT EXISTS buyers (\n                    buyer TEXT PRIMARY KEY, first_order_id TEXT NOT NULL UNIQUE,\n                    bonus_state TEXT NOT NULL DEFAULT \'pending\');\n            \'\'\')\n            if \'disabled\' not in {r[1] for r in c.execute(\'PRAGMA table_info(accounts)\')}:\n                c.execute(\'ALTER TABLE accounts ADD COLUMN disabled INTEGER NOT NULL DEFAULT 0\')\n            if \'reminder_expires\' not in {r[1] for r in c.execute(\'PRAGMA table_info(rentals)\')}:\n                c.execute(\'ALTER TABLE rentals ADD COLUMN reminder_expires REAL\')\n            if \'bonus_deadline\' not in {r[1] for r in c.execute(\'PRAGMA table_info(rentals)\')}:\n                c.execute(\'ALTER TABLE rentals ADD COLUMN bonus_deadline REAL\')\n                c.execute(\'UPDATE rentals SET bonus_deadline=expires\')\n            c.execute(\'\'\'INSERT OR IGNORE INTO purchases(order_id,buyer,chat,seconds,kind,rental_id,created)\n                SELECT order_id,buyer,chat,seconds,\'initial\',order_id,0 FROM rentals ORDER BY rowid\'\'\')\n            c.execute(\'\'\'INSERT OR IGNORE INTO buyers(buyer,first_order_id)\n                SELECT buyer,order_id FROM purchases ORDER BY rowid\'\'\')\n\n    @contextmanager\n    def db(self):\n        c = sqlite3.connect(self.path, timeout=30, isolation_level=None)\n        c.row_factory = sqlite3.Row\n        c.execute(\'PRAGMA foreign_keys=ON\')\n        c.execute(\'BEGIN IMMEDIATE\')\n        try:\n            yield c\n            c.commit()\n        except BaseException:\n            c.rollback()\n            raise\n        finally:\n            c.close()\n\n    def add(self, email, pickup):\n        auth = credentials(email, pickup)\n        with self.db() as c:\n            c.execute(\'INSERT INTO accounts(email,pickup) VALUES (?,?)\', (email, auth.pickup_url()))\n\n    def usage(self, account_id, five, seven, now=None):\n        now = time.time() if now is None else now\n        if any(isinstance(x, bool) or not isinstance(x, (float, int)) or\n               not math.isfinite(x) or not 0 <= x <= 100 for x in (five, seven)):\n            raise ValueError(\'Usage must contain two percentages from 0 to 100\')\n        with self.db() as c:\n            c.execute("UPDATE accounts SET five=?,seven=?,checked=?,state=CASE WHEN state=\'quarantine\' THEN state ELSE ? END WHERE id=?",\n                      (five, seven, now, \'hold\' if max(five, seven) > 70 else \'ready\', account_id))\n\n    def hold(self, account_id):\n        with self.db() as c:\n            c.execute("UPDATE accounts SET state=CASE WHEN state=\'quarantine\' THEN state ELSE \'hold\' END,checked=NULL WHERE id=?", (account_id,))\n\n    def initialized(self, account_id):\n        with self.db() as c:\n            c.execute("UPDATE accounts SET state=\'hold\',checked=NULL WHERE id=? AND state=\'quarantine\'", (account_id,))\n\n    @staticmethod\n    def _record(c, order_id, buyer, chat, seconds, now):\n        if type(seconds) is not int or not 0 < seconds <= 31 * 86400:\n            raise ValueError(\'Invalid rental duration\')\n        order_id, buyer, chat = str(order_id), str(buyer), str(chat)\n        c.execute(\'INSERT OR IGNORE INTO purchases(order_id,buyer,chat,seconds,created) VALUES (?,?,?,?,?)\',\n                  (order_id, buyer, chat, seconds, now))\n        p = c.execute(\'SELECT * FROM purchases WHERE order_id=?\', (order_id,)).fetchone()\n        if (p[\'buyer\'], p[\'chat\'], p[\'seconds\']) != (buyer, chat, seconds):\n            raise ValueError(\'Order parameters mismatch\')\n        c.execute(\'INSERT OR IGNORE INTO buyers(buyer,first_order_id) VALUES (?,?)\', (buyer, order_id))\n        return dict(p)\n\n    def record_purchase(self, order_id, buyer, chat, seconds, now=None):\n        with self.db() as c:\n            return self._record(c, order_id, buyer, chat, seconds, time.time() if now is None else now)\n\n    def renew(self, order_id, buyer, chat, seconds, now=None):\n        now = time.time() if now is None else now\n        with self.db() as c:\n            p = self._record(c, order_id, buyer, chat, seconds, now)\n            if p[\'kind\'] != \'pending\':\n                return {\'duplicate\': True}\n            leases = c.execute("SELECT * FROM rentals WHERE buyer=? AND state!=\'closed\' AND expires>?",\n                               (str(buyer), now)).fetchall()\n            if not leases:\n                return None\n            if len(leases) != 1 or leases[0][\'state\'] != \'active\':\n                raise Unavailable(\'Previous rental is not ready for renewal\')\n            r = leases[0]\n            expires = r[\'expires\'] + seconds\n            c.execute(\'UPDATE rentals SET expires=?,seconds=seconds+? WHERE order_id=?\', (expires, seconds, r[\'order_id\']))\n            c.execute("UPDATE purchases SET kind=\'extension\',rental_id=? WHERE order_id=?", (r[\'order_id\'], str(order_id)))\n            return {\'duplicate\': False, \'expires\': expires, \'account_id\': r[\'account_id\']}\n\n    def is_first_purchase(self, order_id, buyer):\n        with self.db() as c:\n            r = c.execute(\'SELECT first_order_id FROM buyers WHERE buyer=?\', (str(buyer),)).fetchone()\n            return r is not None and r[0] == str(order_id)\n\n    def award_review_bonus(self, order_id, buyer, now=None):\n        now = time.time() if now is None else now\n        with self.db() as c:\n            b = c.execute(\'SELECT * FROM buyers WHERE buyer=?\', (str(buyer),)).fetchone()\n            if not b or b[\'first_order_id\'] != str(order_id) or b[\'bonus_state\'] != \'pending\':\n                return None\n            r = c.execute(\'SELECT * FROM rentals WHERE order_id=? AND buyer=?\', (str(order_id), str(buyer))).fetchone()\n            if not r or (r[\'state\'] == \'issuing\' and r[\'expires\'] > now):\n                return None\n            eligible = r[\'state\'] == \'active\' and min(r[\'expires\'], r[\'bonus_deadline\'] or r[\'expires\']) > now\n            state = \'awarded\' if eligible else \'too_late\'\n            c.execute(\'UPDATE buyers SET bonus_state=? WHERE buyer=?\', (state, str(buyer)))\n            if eligible:\n                c.execute(\'UPDATE rentals SET expires=expires+3600,seconds=seconds+3600 WHERE order_id=?\', (str(order_id),))\n            return {\'state\': state, \'chat\': r[\'chat\'], \'expires\': r[\'expires\'] + (3600 if eligible else 0)}\n\n    def review_candidates(self):\n        with self.db() as c:\n            return [r[0] for r in c.execute(\'\'\'SELECT b.first_order_id FROM buyers b JOIN rentals r\n                ON r.order_id=b.first_order_id WHERE b.bonus_state=\'pending\' AND r.state=\'active\'\n                AND r.bonus_deadline>? ORDER BY r.rowid\'\'\', (time.time(),))]\n\n    def claim_reminders(self, now=None, lead_seconds=900):\n        now = time.time() if now is None else now\n        with self.db() as c:\n            rows = [dict(r) for r in c.execute(\'\'\'SELECT order_id,chat,expires FROM rentals\n                WHERE state=\'active\' AND expires>? AND expires<=?\n                AND (reminder_expires IS NULL OR reminder_expires!=expires)\'\'\', (now, now + lead_seconds))]\n            for r in rows:\n                c.execute(\'UPDATE rentals SET reminder_expires=? WHERE order_id=?\', (r[\'expires\'], r[\'order_id\']))\n            return rows\n\n    def reserve(self, order_id, buyer, chat, seconds, now=None):\n        now = time.time() if now is None else now\n        if type(seconds) is not int or not 0 < seconds <= 31 * 86400:\n            raise ValueError(\'Invalid rental duration\')\n        with self.db() as c:\n            p = self._record(c, order_id, buyer, chat, seconds, now)\n            old = c.execute(\'SELECT * FROM rentals WHERE order_id=?\', (order_id,)).fetchone()\n            if old:\n                if old[\'buyer\'] != str(buyer) or old[\'chat\'] != str(chat):\n                    raise ValueError(\'Order owner mismatch\')\n                return None  # Duplicate events never issue another login code.\n            if p[\'kind\'] != \'pending\':\n                return None\n            if c.execute("SELECT 1 FROM rentals WHERE buyer=? AND state!=\'closed\' AND expires>?",\n                         (str(buyer), now)).fetchone():\n                raise Unavailable(\'Buyer already has an active rental; renew it instead\')\n            a = c.execute(\'\'\'SELECT * FROM accounts a WHERE state=\'ready\' AND disabled=0\n                AND checked BETWEEN ? AND ? AND five<=70 AND seven<=70\n                AND NOT EXISTS (SELECT 1 FROM rentals r WHERE r.account_id=a.id AND r.state!=\'closed\')\n                ORDER BY MAX(five,seven),id LIMIT 1\'\'\', (now - 120, now)).fetchone()\n            if not a:\n                raise Unavailable(\'No account with fresh usage and confirmed session cleanup\')\n            c.execute(\'INSERT INTO rentals(order_id,buyer,chat,account_id,seconds,state,expires,code_hash) VALUES (?,?,?,?,?,?,?,?)\',\n                      (str(order_id), str(buyer), str(chat), a[\'id\'], seconds,\n                       \'issuing\', now + seconds, None))\n            c.execute("UPDATE purchases SET kind=\'initial\',rental_id=? WHERE order_id=?", (str(order_id), str(order_id)))\n            return dict(a)\n\n    def claim_code(self, order_id, code):\n        message_id = None\n        if isinstance(code, dict):\n            message_id = code.get(\'message_id\')\n            code = code.get(\'value\')\n            if type(message_id) is not int or message_id <= 0:\n                raise ValueError(\'Invalid mail message ID\')\n        code = login_value(code)\n        if code.isdigit() and message_id is None:\n            raise ValueError(\'Numeric codes require a mail message ID\')\n        digest = hashlib.sha256(code.encode()).hexdigest()\n        with self.db() as c:\n            if message_id is not None:\n                r = c.execute(\'SELECT account_id FROM rentals WHERE order_id=?\', (order_id,)).fetchone()\n                if r is None:\n                    raise Unavailable(\'Order not found\')\n                c.execute(\'INSERT INTO mail_claims VALUES (?,?,?)\', (r[0], message_id, order_id))\n            result = c.execute("UPDATE rentals SET code_hash=? WHERE order_id=? AND state=\'issuing\' AND code_hash IS NULL",\n                               (digest, order_id))\n            if result.rowcount != 1:\n                raise Unavailable(\'Code already claimed\')\n        return code\n\n    def active(self, order_id, now=None):\n        now = time.time() if now is None else now\n        with self.db() as c:\n            c.execute("UPDATE rentals SET state=\'active\',expires=?+seconds,bonus_deadline=?+seconds WHERE order_id=? AND state=\'issuing\'",\n                      (now, now, order_id))\n\n    def pending_cleanup(self, now=None):\n        now = time.time() if now is None else now\n        with self.db() as c:\n            c.execute("UPDATE rentals SET state=\'cleanup\' WHERE state IN (\'active\',\'issuing\') AND expires<=?", (now,))\n            return [dict(r) for r in c.execute(\'\'\'SELECT r.*,a.email,a.pickup FROM rentals r\n                JOIN accounts a ON a.id=r.account_id WHERE r.state=\'cleanup\' \'\'\')]\n\n    def close(self, order_id):\n        with self.db() as c:\n            r = c.execute(\'SELECT account_id FROM rentals WHERE order_id=?\', (order_id,)).fetchone()\n            c.execute("UPDATE accounts SET state=\'hold\',checked=NULL WHERE id=?", (r[0],))\n            c.execute("UPDATE rentals SET state=\'closed\' WHERE order_id=? AND state=\'cleanup\'", (order_id,))\n\n    def accounts(self):\n        with self.db() as c:\n            return [dict(r) for r in c.execute(\'SELECT * FROM accounts\')]\n\n    def set_disabled(self, account_id, disabled):\n        with self.db() as c:\n            result = c.execute(\'UPDATE accounts SET disabled=? WHERE id=?\', (int(disabled), account_id))\n            if result.rowcount != 1:\n                raise ValueError(\'Account not found\')\n\n    def admin_accounts(self):\n        with self.db() as c:\n            return [dict(r) for r in c.execute(\'\'\'SELECT a.id,a.email,a.state,a.disabled,a.five,a.seven,\n                r.order_id,r.state AS rental_state,r.expires FROM accounts a LEFT JOIN rentals r\n                ON a.id=r.account_id AND r.state!=\'closed\' ORDER BY a.id\'\'\')]\n\n    def recent_rentals(self):\n        with self.db() as c:\n            return [dict(r) for r in c.execute(\'\'\'SELECT order_id,account_id,state,expires,seconds\n                FROM rentals ORDER BY rowid DESC LIMIT 20\'\'\')]\n\n\nclass Engine:\n    """Provider contract: usage, issue, revoke_all. No simulated success in production."""\n    def __init__(self, store, provider, send):\n        self.store, self.provider, self.send = store, provider, send\n\n    def tick(self):\n        for r in self.store.pending_cleanup():\n            try:\n                # Must verify remote invalidation, including any reusable login link.\n                if self.provider.revoke_all(r) is True:\n                    self.store.close(r[\'order_id\'])\n            except Exception:\n                pass  # Keep exclusive reservation; never free on a network error.\n        for a in self.store.accounts():\n            try:\n                if a[\'state\'] == \'quarantine\':\n                    if self.provider.revoke_all({**a, \'account_id\': a[\'id\'],\n                                                 \'order_id\': f"initialize-{a[\'id\']}"}) is not True:\n                        continue\n                    self.store.initialized(a[\'id\'])\n                five, seven = self.provider.usage(a)\n                self.store.usage(a[\'id\'], five, seven)\n            except Exception:\n                self.store.hold(a[\'id\'])\n\n    def deliver(self, order_id, buyer, chat, seconds):\n        renewal = self.store.renew(order_id, buyer, chat, seconds)\n        if renewal is not None:\n            if renewal.get(\'duplicate\'):\n                return False\n            self.notify_renewal(chat, seconds, renewal)\n            return True\n        a = self.store.reserve(order_id, buyer, chat, seconds)\n        if a is None:\n            return False\n        first = self.store.is_first_purchase(order_id, buyer)\n        greeting = (f\'Здравствуйте! Спасибо за покупку. Аренда Claude: {format_duration(seconds)}.\\n\'\n                    f\'Ваша почта: {a["email"]}\\nКод или ссылка входа выдаётся только один раз на эту аренду. \'\n                    \'Сейчас подготовлю вход. При продлении новый код не нужен.\')\n        if first:\n            greeting += (\'\\nЭто ваша первая покупка: +1 час за отзыв к этому заказу, \'\n                         \'если бот подтвердит его до окончания первоначального срока аренды. Оставьте отзыв сразу; \'\n                         \'позже бонус не начисляется. Продление не увеличивает срок для получения бонуса.\')\n        else:\n            greeting += \'\\nБонус за отзыв действует только при первой покупке.\'\n        if not self.send(chat, greeting):\n            raise Unavailable(\'Greeting unconfirmed; account remains reserved\')\n        # On exception or crash leave issuing until expiry and verified cleanup.\n        code = self.store.claim_code(order_id, self.provider.issue(a, order_id))\n        if not self.send(chat, f"Вход: {code}\\nСрок: {format_duration(seconds)}. Код выдан один раз; повторной выдачи нет."):\n            raise Unavailable(\'Delivery unconfirmed; account remains reserved\')\n        self.store.active(order_id)\n        return True\n\n    def notify_renewal(self, chat, seconds, renewal):\n        if not self.send(chat, f\'Аренда продлена на {format_duration(seconds)}. Окончание: {end_time(renewal["expires"])}. \'\n                         \'Оставайтесь в том же аккаунте: новый код при продлении не выдаётся.\'):\n            raise Unavailable(\'Rental extended, notification unconfirmed\')\n\n    def remind(self):\n        failed = False\n        for r in self.store.claim_reminders():\n            with self.store.db() as c:\n                current = c.execute("SELECT 1 FROM rentals WHERE order_id=? AND state=\'active\' AND expires=? AND expires>?",\n                                    (r[\'order_id\'], r[\'expires\'], time.time())).fetchone()\n            if not current:\n                continue\n            minutes = max(1, math.ceil((r[\'expires\'] - time.time()) / 60))\n            try:\n                if not self.send(r[\'chat\'], f\'Аренда заканчивается примерно через {minutes} мин — {end_time(r["expires"])}. \'\n                                 \'Для продления до окончания аренды купите лот на нужный срок. Время добавится к текущему аккаунту, новый код не нужен.\'):\n                    failed = True\n            except Exception:\n                failed = True\n        if failed:\n            raise Unavailable(\'Some reminder deliveries were not confirmed\')\n\n    def apply_review(self, order_id, buyer):\n        result = self.store.award_review_bonus(order_id, buyer)\n        if result:\n            text = (f\'Спасибо за отзыв к первой покупке! Начислен +1 час. Окончание: {end_time(result["expires"])}.\'\n                    if result[\'state\'] == \'awarded\' else\n                    \'Отзыв подтверждён после первоначального срока первой аренды: бонусный час не начислен. \'\n                    \'Оставлять отзыв нужно сразу; продление не увеличивает срок для бонуса.\')\n            if not self.send(result[\'chat\'], text):\n                raise Unavailable(\'Review processed, notification unconfirmed\')\n        return result\n\n\ndef main():\n    p = argparse.ArgumentParser()\n    p.add_argument(\'--db\', default=\'data/rentals.sqlite3\')\n    p.add_argument(\'command\', choices=[\'add\', \'status\'])\n    args = p.parse_args()\n    s = Store(args.db)\n    if args.command == \'add\':\n        import getpass\n        s.add(input(\'Email: \').strip(), getpass.getpass(\'Pickup URL (hidden): \').strip())\n    else:\n        # Pickup URLs, emails and login codes are deliberately omitted.\n        print(json.dumps([{k: a[k] for k in (\'id\', \'state\', \'five\', \'seven\', \'checked\')}\n                          for a in s.accounts()], indent=2))\n\n\nif __name__ == \'__main__\':\n    main()\n', 'claude_browser_actions': '# noplug\n"""Locale-aware browser actions for a future validated Claude adapter.\n\nThis module neither logs in nor claims that UI clicks revoke Claude Code tokens.\nThe caller supplies identity and remote revocation checks on its own browser worker.\n"""\nimport re\nfrom urllib.parse import urlsplit\n\n\nclass LogoutError(Exception):\n    pass\n\n\nGLOBAL_LABELS = {\n    \'ru\': (\'Выйти везде\', \'Выйти на всех устройствах\', \'Выйти из всех сеансов\', \'Завершить все сеансы\'),\n    \'en\': (\'Log out everywhere\', \'Log out of all devices\', \'Log out all devices\',\n           \'Log out of all sessions\', \'Sign out everywhere\', \'Sign out of all devices\'),\n    \'uk\': (\'Вийти скрізь\', \'Вийти на всіх пристроях\', \'Завершити всі сеанси\'),\n    \'de\': (\'Überall abmelden\', \'Von allen Geräten abmelden\', \'Auf allen Geräten abmelden\'),\n    \'fr\': (\'Se déconnecter de tous les appareils\', \'Déconnexion de tous les appareils\'),\n    \'es\': (\'Cerrar sesión en todos los dispositivos\', \'Cerrar todas las sesiones\'),\n    \'pt\': (\'Sair de todos os dispositivos\', \'Encerrar todas as sessões\'),\n    \'zh\': (\'退出所有设备\', \'登出所有裝置\', \'登出所有设备\'),\n    \'ja\': (\'すべてのデバイスからログアウト\', \'すべてのデバイスでログアウト\'),\n    \'ko\': (\'모든 기기에서 로그아웃\', \'모든 장치에서 로그아웃\'),\n}\nCONFIRM_LABELS = (\'Выйти\', \'Подтвердить\', \'Завершить сеансы\', \'Log out\', \'Sign out\', \'Confirm\',\n                  \'Вийти\', \'Підтвердити\', \'Abmelden\', \'Bestätigen\', \'Se déconnecter\', \'Confirmer\',\n                  \'Cerrar sesión\', \'Confirmar\', \'Sair\', \'退出\', \'登出\', \'确认\', \'確認\',\n                  \'ログアウト\', \'로그아웃\', \'확인\')\n\n\ndef _pattern(labels):\n    return re.compile(r\'^\\s*(?:\' + \'|\'.join(re.escape(x) for x in labels) + r\')\\s*(?:…|\\.\\.\\.)?\\s*$\', re.I)\n\n\ndef _visible(locator):\n    return [locator.nth(i) for i in range(locator.count()) if locator.nth(i).is_visible()]\n\n\ndef logout_everywhere(page, *, verify_account, verify_revoked, timeout_ms=10000):\n    """Click the global logout action and confirm it in a visible modal, if any.\n\n    page: authenticated Playwright Page already displaying the real account settings.\n    verify_account(page) must confirm the expected account, without guessing.\n    verify_revoked(timeout_ms) must test old independent sessions/tokens, including\n    Code if sold, and the previous login link. Return True only after these checks.\n    Unknown labels, ambiguous buttons and failed checks raise LogoutError. The rental\n    must remain in cleanup; the caller must not catch this and return True.\n    Playwright is optional: this module is imported without launching a browser.\n    """\n    labels = tuple(x for values in GLOBAL_LABELS.values() for x in values)\n    try:\n        url = urlsplit(page.url)\n        if url.scheme != \'https\' or url.hostname != \'claude.ai\' or url.port not in (None, 443) or url.username:\n            raise LogoutError(\'Unexpected settings origin\')\n        if not callable(verify_account) or not callable(verify_revoked) or verify_account(page) is not True:\n            raise LogoutError(\'Account identity was not confirmed\')\n        if not 100 <= timeout_ms <= 60000:\n            raise LogoutError(\'Invalid browser timeout\')\n        dialogs = page.get_by_role(\'dialog\').or_(page.get_by_role(\'alertdialog\'))\n        existing_dialogs = [d.element_handle() for d in _visible(dialogs)]\n        buttons = _visible(page.get_by_role(\'button\', name=_pattern(labels)))\n        if len(buttons) != 1:\n            raise LogoutError(\'A unique global logout button was not found; account remains held\')\n        buttons[0].click(timeout=timeout_ms)\n        # A direct logout may have no modal. If a modal appears, scope the confirm\n        # search to it so a local logout elsewhere on the page can never be clicked.\n        try:\n            page.wait_for_function(\'\'\'previous => [...document.querySelectorAll(\'dialog,[role="dialog"],[role="alertdialog"]\')]\n                .some(el => !previous.includes(el) && el.getClientRects().length &&\n                    getComputedStyle(el).visibility !== \'hidden\')\'\'\', arg=existing_dialogs,\n                timeout=min(1500, timeout_ms))\n        except Exception as exc:\n            if type(exc).__name__ != \'TimeoutError\':\n                raise\n        # The screenshot\'s Settings window is itself a dialog. Only a newly\n        # opened confirmation may receive the second click.\n        visible = [d for d in _visible(dialogs)\n                   if d.evaluate(\'(el, previous) => !previous.includes(el)\', existing_dialogs)]\n        if len(visible) > 1:\n            raise LogoutError(\'Multiple confirmation dialogs; account remains held\')\n        if visible:\n            confirm = _visible(visible[0].get_by_role(\'button\', name=_pattern(labels + CONFIRM_LABELS)))\n            if len(confirm) != 1:\n                raise LogoutError(\'A unique logout confirmation was not found; account remains held\')\n            confirm[0].click(timeout=timeout_ms)\n        if verify_revoked(timeout_ms) is not True:\n            raise LogoutError(\'Logout was clicked but revocation was not confirmed; account remains held\')\n        return True\n    except LogoutError:\n        raise\n    except Exception:\n        # Browser errors can contain URLs, HTML, account data and session tokens.\n        raise LogoutError(\'Browser action failed; account remains held\') from None\n', 'lot_rules': '# noplug\n"""Explicit paid durations; review bonuses are not part of the purchase title."""\nfrom decimal import Decimal, InvalidOperation\nimport re\n\nLEGACY_RULES = [{\'pattern\': \'(?i)Claude PRO.*НА 5 ЧАСОВ.*АРЕНДА\', \'hours\': 5,\n                 \'quantity_is_duration\': False}]\nPAID_TERM = re.compile(r\'\\b(?:на|аренда)\\s*(\\d+)\\s*(минут(?:а|ы)?|мин\\.?|час(?:а|ов)?|ч\\.?)\\b\', re.I)\n\n\ndef literal_pattern(title):\n    # Cardinal appends the bought quantity to OrderShortcut.description.\n    return r\'(?i)^\' + re.escape(title) + r\'(?:,\\s+\\d[\\d ]*\\s+(?:шт|pcs)\\.)?$\'\n\n\ndef default_rules():\n    rules = []\n    for minutes, phrase, label in [(30, r\'30\\s*мин(?:ут(?:а|ы)?)?\', \'Claude — 30 минут\'),\n                                   (60, r\'1\\s*час(?:а|ов)?\', \'Claude — 1 час\'),\n                                   (120, r\'2\\s*час(?:а|ов)?\', \'Claude — 2 часа\'),\n                                   (180, r\'3\\s*час(?:а|ов)?\', \'Claude — 3 часа\'),\n                                   (300, r\'5\\s*час(?:а|ов)?\', \'Claude — 5 часов\')]:\n        rules.append({\'label\': label, \'pattern\': r\'(?i)(?=.*\\bClaude\\b)(?=.*\\bаренда\\b).*\\b(?:на|аренда)\\s*\' + phrase + r\'\\b\',\n                      \'minutes\': minutes, \'quantity_is_duration\': True, \'check_paid_term\': True})\n    return rules\n\n\ndef rule_seconds(rule):\n    keys = [k for k in (\'seconds\', \'minutes\', \'hours\') if k in rule]\n    if len(keys) != 1 or isinstance(rule[keys[0]], bool):\n        raise ValueError(\'Specify exactly one duration unit\')\n    try:\n        value = Decimal(str(rule[keys[0]])) * {\'seconds\': 1, \'minutes\': 60, \'hours\': 3600}[keys[0]]\n        if not value.is_finite() or value != value.to_integral_value() or not 0 < value <= 31 * 86400:\n            raise ValueError(\'Invalid duration\')\n        return int(value)\n    except InvalidOperation:\n        raise ValueError(\'Invalid duration\') from None\n\n\ndef duration(description, amount, rules):\n    suffix = re.search(r\',\\s+(\\d[\\d ]*)\\s+(?:шт|pcs)\\.\\s*$\', description, re.I)\n    if suffix:\n        if int(suffix[1].replace(\' \', \'\')) != amount:\n            raise ValueError(\'Order quantity and description disagree\')\n        description = description[:suffix.start()]\n    matches = [r for r in rules if re.search(r[\'pattern\'], description)]\n    if not matches:\n        return None\n    if len(matches) != 1:\n        raise ValueError(\'Ambiguous rental rule\')\n    rule = matches[0]\n    seconds = rule_seconds(rule)\n    if rule.get(\'check_paid_term\'):\n        terms = PAID_TERM.findall(description)\n        if len(terms) != 1:\n            raise ValueError(\'Ambiguous paid duration\')\n        value, unit = terms[0]\n        if int(value) * (60 if unit.casefold().startswith(\'мин\') else 3600) != seconds:\n            raise ValueError(\'Title and configured duration disagree\')\n    units = amount if rule.get(\'quantity_is_duration\', False) else 1\n    if type(units) is not int or units < 1 or seconds * units > 31 * 86400:\n        raise ValueError(\'Invalid order quantity\')\n    return seconds * units\n\n\ndef parse_minutes(text):\n    match = re.fullmatch(r\'\\s*([1-9]\\d*)\\s*(мин(?:ут(?:а|ы)?)?\\.?|ч(?:ас(?:а|ов)?)?\\.?)?\\s*\', text, re.I)\n    if not match:\n        raise ValueError(\'Enter 30 мин or 1 час\')\n    minutes = int(match[1]) * (60 if (match[2] or \'\').casefold().startswith(\'ч\') else 1)\n    if not 1 <= minutes <= 31 * 1440:\n        raise ValueError(\'Invalid duration\')\n    return minutes\n'}

"""Claude Rental plugin for FunPay Cardinal 0.1.17.15.
Source edition uses sibling helper modules. dist/ contains a single-file build.
"""
import copy
import importlib.util
import json
import logging
import os
from pathlib import Path
import queue
import re
import sqlite3
import sys
import tempfile
import threading
import time
from types import ModuleType
from email.utils import parseaddr

NAME = 'Claude Rental'
VERSION = '0.3.6'
DESCRIPTION = 'Аренда Claude: аккаунты, почта Remail и управление выдачей. Требуется Claude-адаптер.'
CREDITS = 'Local development'
UUID = '52280b60-3fd9-4df7-9eb3-f1bb1cd337ef'
SETTINGS_PAGE = True
log = logging.getLogger('FPC.claude_rental')
_runtime = None


def load_rules_module():
    source = globals().get('_EMBEDDED_SOURCES', {}).get('lot_rules')
    if source is None:
        source = Path(__file__).with_name('lot_rules.py').read_text(encoding='utf-8')
    module = ModuleType('_claude_rental_rules')
    sys.modules[module.__name__] = module
    exec(compile(source, '<claude_rental/lot_rules.py>', 'exec'), module.__dict__)
    return module


rules_module = load_rules_module()
duration = rules_module.duration
DEFAULT_CONFIG = {
    'database': 'storage/claude_rental/rentals.sqlite3',
    'claude_provider_file': '',
    'enabled': False,
    'rules_schema': 1,
    'mailbox': {'allowed_senders': [], 'poll_seconds': 5, 'timeout_seconds': 120},
    'rules': rules_module.default_rules(),
}


def load_file(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def components():
    # Release embeds Python sources, never credentials or databases.
    sources = globals().get('_EMBEDDED_SOURCES')
    if sources is None:
        sources = {name: Path(__file__).with_name(name + '.py').read_text(encoding='utf-8')
                   for name in ('remail', 'rental', 'claude_browser_actions')}
    modules = {}
    for name in ('remail', 'rental', 'claude_browser_actions'):
        module_name = '_claude_rental_browser_actions' if name == 'claude_browser_actions' else '_claude_rental_' + name
        module = ModuleType(module_name)
        sys.modules[module_name] = module
        source = sources[name].replace('from remail import credentials, login_value',
                                      'from _claude_rental_remail import credentials, login_value')
        exec(compile(source, f'<claude_rental/{name}.py>', 'exec'), module.__dict__)
        modules[name] = module
    return modules['rental'], modules['remail']


class Runtime:
    def __init__(self, cardinal, config_path):
        self.cardinal = cardinal
        self.path = Path(config_path)
        self.core, self.mail = components()
        self.config = copy.deepcopy(DEFAULT_CONFIG)
        if self.path.exists():
            saved = json.loads(self.path.read_text(encoding='utf-8'))
            self.config.update(saved)
            self.config['mailbox'] = {**DEFAULT_CONFIG['mailbox'], **saved.get('mailbox', {})}
            migrated = False
            if saved.get('rules') == rules_module.LEGACY_RULES:
                self.config['rules'] = rules_module.default_rules()
                migrated = True
            if saved.get('rules_schema', 0) < 1:
                for rule in self.config['rules']:
                    rule['quantity_is_duration'] = True
                self.config['rules_schema'] = 1
                migrated = True
            if migrated:
                self.save_config()
        else:
            self.save_config()
        self.store = self.core.Store(self.config['database'])
        self.engine = None
        self.status = 'Не подключён Claude-адаптер. Почта и управление аккаунтами доступны.'
        self.last_error = ''
        self.lock = threading.RLock()
        self.provider_lock = threading.Lock()
        self.stop = threading.Event()
        self.orders = queue.Queue(maxsize=500)
        self.queued = set()
        self.reviews = queue.Queue(maxsize=500)
        self.review_poll_at = 0
        self.review_cursor = 0
        self.threads = []
        self.connect_provider()

    def save_config(self):
        self.path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        fd, temp = tempfile.mkstemp(prefix='.config-', dir=self.path.parent)
        try:
            with os.fdopen(fd, 'w', encoding='utf-8') as f:
                json.dump(self.config, f, ensure_ascii=False, indent=2)
                f.write('\n')
            os.replace(temp, self.path)
        finally:
            if os.path.exists(temp):
                os.unlink(temp)

    def connect_provider(self):
        path = self.config.get('claude_provider_file') or self.config.get('provider_file')
        if not path or not Path(path).is_file():
            return
        try:
            external = load_file('_claude_rental_provider', path).create(self.config)
            if self.config.get('claude_provider_file'):
                self.mail.Mailbox(None, self.config['mailbox']['allowed_senders'])
                for method in ('usage', 'request_login', 'revoke_all'):
                    if not callable(getattr(external, method, None)):
                        raise ValueError('Invalid Claude provider')
                provider = self.mail.Provider(external, self.config['mailbox'])
            else:
                provider = external
            self.engine = self.core.Engine(self.store, provider, self.send)
            self.status = 'Claude-адаптер загружен; готовность аккаунтов проверяется отдельно.'
        except Exception:
            self.status = 'Не удалось загрузить Claude-адаптер. Проверьте файл и отправителя писем.'

    def send(self, chat, text):
        return bool(self.cardinal.send_message(chat, text, attempts=1, watermark=False))

    def available(self):
        plugin = self.cardinal.plugins.get(UUID)
        return plugin is not None and plugin.enabled

    def enqueue(self, order):
        with self.lock:
            if not self.available():
                return
            if order.status.name != 'PAID':
                return
            seconds = duration(order.description, order.amount, self.config['rules'])
            if seconds is None or str(order.id) in self.queued:
                return
            task = (str(order.id), str(order.buyer_id), str(order.chat_id), seconds)
            self.store.record_purchase(*task)
            if not self.config['enabled'] or self.engine is None:
                return
            # Extend in the payment callback so another customer's mailbox wait
            # cannot let an active rental expire. Only the notice is queued.
            try:
                renewal = self.store.renew(*task)
            except self.core.Unavailable:
                renewal = None  # First delivery is still in progress; process in order.
            if renewal is not None:
                if renewal.get('duplicate'):
                    return
                task = (*task, renewal)
            self.orders.put_nowait(task)
            self.queued.add(task[0])

    def check_review(self, order):
        review = getattr(order, 'review', None)
        if (self.engine is None or order.status.name not in ('PAID', 'CLOSED') or review is None
                or type(review.stars) is not int or not 1 <= review.stars <= 5 or getattr(review, 'hidden', False)):
            return
        author = getattr(review, 'author_id', None)
        if author is not None and str(author) != str(order.buyer_id):
            return
        self.engine.apply_review(str(order.id), str(order.buyer_id))

    def queue_review(self, kind, value):
        if self.available():
            try:
                self.reviews.put_nowait((kind, value))
            except queue.Full:
                self.last_error = 'Очередь проверки отзывов заполнена; проверьте отзывы к первым покупкам.'

    def process_one(self, task, stop_event=None):
        stop_event = self.stop if stop_event is None else stop_event
        try:
            if len(task) == 5:
                if not stop_event.is_set() and self.available() and self.engine:
                    self.engine.notify_renewal(task[2], task[3], task[4])
                return
            with self.provider_lock:
                if not stop_event.is_set() and self.available() and self.config['enabled'] and self.engine:
                    self.engine.deliver(*task)
        except Exception:
            self.last_error = f'Заказ {task[0]} требует проверки оператором; повторная выдача не выполняется.'
            log.error('Claude Rental: order requires operator review')
        finally:
            with self.lock:
                self.queued.discard(task[0])

    def start(self):
        if not self.stop.is_set() and any(t.is_alive() for t in self.threads):
            return
        self.stop = run_stop = threading.Event()

        def delivery_worker():
            while not run_stop.is_set():
                try:
                    task = self.orders.get(timeout=1)
                except queue.Empty:
                    continue
                self.process_one(task, run_stop)
                self.orders.task_done()

        def maintenance_worker():
            while not run_stop.is_set():
                if self.engine and self.available():
                    try:
                        self.engine.remind()
                    except Exception:
                        self.last_error = 'Не подтверждена отправка напоминания; проверьте чаты активных аренд.'
                        log.error('Claude Rental: reminder delivery failed')
                    try:
                        if time.time() >= self.review_poll_at:
                            candidates = self.store.review_candidates()
                            if candidates:
                                for i in range(min(5, len(candidates))):
                                    self.queue_review('id', candidates[(self.review_cursor + i) % len(candidates)])
                                self.review_cursor = (self.review_cursor + 5) % len(candidates)
                            self.review_poll_at = time.time() + 60
                        if self.provider_lock.acquire(blocking=False):
                            try:
                                if not run_stop.is_set() and self.available():
                                    self.engine.tick()
                            finally:
                                self.provider_lock.release()
                    except Exception:
                        self.last_error = 'Ошибка фоновой проверки; аккаунты требуют проверки.'
                        log.error('Claude Rental: maintenance failed')
                run_stop.wait(30)

        def review_worker():
            while not run_stop.is_set():
                try:
                    kind, value = self.reviews.get(timeout=1)
                except queue.Empty:
                    continue
                try:
                    if not run_stop.is_set() and self.available():
                        order = (self.cardinal.account.get_order(value) if kind == 'id'
                                 else self.cardinal.get_order_from_object(value))
                        if order is not None:
                            self.check_review(order)
                except Exception:
                    self.last_error = 'Не удалось проверить отзыв через FunPay; бонус пока не начислен.'
                    log.error('Claude Rental: review verification failed')
                finally:
                    self.reviews.task_done()

        self.threads = [threading.Thread(target=f, daemon=True, name='claude-rental-' + label)
                        for f, label in ((delivery_worker, 'orders'), (maintenance_worker, 'maintenance'), (review_worker, 'reviews'))]
        for thread in self.threads:
            thread.start()

    def shutdown(self):
        self.stop.set()


def register_panel(runtime):
    from html import escape
    from telebot.types import InlineKeyboardMarkup, InlineKeyboardButton
    from tg_bot import CBT

    cardinal = runtime.cardinal
    tg = cardinal.telegram
    if not tg:
        return
    bot = tg.bot
    prefix = 'clauderental:'
    state_prefix = 'claude_rental_'

    def permitted(user_id, chat):
        return user_id in tg.authorized_users and chat.type == 'private' and runtime.available()

    def say(chat_id, text, keyboard=None):
        return bot.send_message(chat_id, text, reply_markup=keyboard, parse_mode='HTML')

    def menu(chat_id):
        state = 'включены' if runtime.config['enabled'] else 'на паузе'
        text = (f'<b>Claude Rental {VERSION}</b>\nНовые выдачи: {state}.\n'
                f'{escape(runtime.status)}\nАккаунтов: {len(runtime.store.accounts())}'
                '\nБонус: один раз за первую покупку. Напоминание: за 15 минут.')
        if runtime.last_error:
            text += '\n' + escape(runtime.last_error)
        keyboard = InlineKeyboardMarkup(row_width=2)
        for title, action in [('Аккаунты', 'accounts:0'), ('Добавить аккаунт', 'add'),
                              ('Аренды', 'rentals'), ('Отправители Claude', 'senders'),
                              ('Лоты и сроки', 'rules'), ('Проверить название', 'preview'),
                              ('Пауза / запуск', 'toggle'), ('Обновить', 'menu'), ('Справка', 'help')]:
            keyboard.add(InlineKeyboardButton(title, callback_data=prefix + action))
        say(chat_id, text, keyboard)

    def rule_menu(chat_id):
        keyboard = InlineKeyboardMarkup(row_width=2)
        lines = ['<b>Лоты и точные сроки</b>']
        for i, rule in enumerate(runtime.config['rules']):
            label = rule.get('label', rule['pattern'])[:100]
            suffix = ' × количество' if rule.get('quantity_is_duration') else ' (фиксированный срок)'
            lines.append(f"{i+1}. {escape(label)} → {runtime.core.format_duration(rules_module.rule_seconds(rule))}{suffix}")
            keyboard.row(InlineKeyboardButton(f'Название #{i+1}', callback_data=prefix + f'edit_lot:{i}'),
                         InlineKeyboardButton(f'Срок #{i+1}', callback_data=prefix + f'edit_time:{i}'))
        keyboard.add(InlineKeyboardButton('Добавить лот', callback_data=prefix + 'add_rule'))
        keyboard.add(InlineKeyboardButton('Заменить правила на 5 стандартных', callback_data=prefix + 'reset_rules'))
        say(chat_id, '\n'.join(lines) + '\nСтандартные сроки умножаются на количество купленных единиц. '
            'Час за отзыв сюда не включается.', keyboard)

    def command(m):
        if permitted(m.from_user.id, m.chat):
            tg.clear_state(m.chat.id, m.from_user.id)
            menu(m.chat.id)

    def ask(c, state, text, data=None):
        result = say(c.message.chat.id, text + '\nОтмена: /claude_rental')
        tg.set_state(c.message.chat.id, result.id, c.from_user.id, state_prefix + state, data)

    def callback(c):
        if not permitted(c.from_user.id, c.message.chat):
            bot.answer_callback_query(c.id, 'Доступ только администратору в личном чате.')
            return
        bot.answer_callback_query(c.id)
        action = c.data[len(prefix):] if c.data.startswith(prefix) else 'menu'
        chat_id = c.message.chat.id
        try:
            if action == 'menu':
                menu(chat_id)
            elif action == 'add':
                ask(c, 'email', 'Введите точную почту аккаунта Claude.')
            elif action == 'senders':
                current = ', '.join(runtime.config['mailbox']['allowed_senders']) or 'не заданы'
                ask(c, 'senders', f'Сейчас: {escape(current)}\nВведите адрес из поля «От кого» настоящего письма входа Claude. '
                    'Это не ваша почта и не ссылка Remail. Несколько адресов разделите запятой.')
            elif action in ('rules', 'lot', 'hours'):
                rule_menu(chat_id)
            elif action == 'reset_rules':
                with runtime.lock:
                    runtime.config['rules'] = rules_module.default_rules()
                    runtime.save_config()
                rule_menu(chat_id)
            elif action == 'preview':
                ask(c, 'preview', 'Вставьте название лота: покажу срок одной единицы без покупки и выдачи кода.')
            elif action == 'add_rule':
                ask(c, 'new_rule_title', 'Вставьте полное название нового лота.')
            elif action.startswith(('edit_lot:', 'edit_time:')):
                index = int(action.split(':')[1])
                data = {'index': index, 'before': copy.deepcopy(runtime.config['rules'][index])}
                if action.startswith('edit_lot:'):
                    ask(c, 'rule_title', 'Вставьте полное название лота для этого правила.', data)
                else:
                    ask(c, 'rule_minutes', 'Введите срок: 30 мин, 1 час, 2 часа и т. п. Число без единицы означает минуты.', data)
            elif action == 'help':
                say(chat_id, '<b>Как пользоваться</b>\n'
                    'Аккаунты — список, лимиты, проверка почты и исключение из выдачи.\n'
                    'Добавить аккаунт — ваша почта и персональная ссылка Remail.\n'
                    'Аренды — заказы и время окончания по Москве.\n'
                    'Отправители Claude — поле «От кого» в письме входа, не ваша почта.\n'
                    'Лоты и сроки — отдельное правило для каждого срока.\n'
                    'Проверить название — проверка распознавания без покупки.\n'
                    'Пауза / запуск — обработка новых покупок; текущие аренды продолжаются.\n'
                    'Обновить — перечитать состояние меню.\n\n'
                    'Бонус +1 час: один раз за проверенный отзыв к первой покупке до окончания первой аренды. '
                    'Продление: новый оплаченный лот во время аренды добавляет время без нового кода. '
                    'Напоминание приходит примерно за 15 минут. '
                    'Для реальных выдач и выхода из Claude нужен подключённый Claude-адаптер.')
            elif action == 'toggle':
                with runtime.lock:
                    if not runtime.config['enabled'] and runtime.engine is None:
                        say(chat_id, 'Нельзя включить выдачу: Claude-адаптер не подключён. После его настройки перезапустите Cardinal.')
                        return
                    runtime.config['enabled'] = not runtime.config['enabled']
                    runtime.save_config()
                menu(chat_id)
            elif action.startswith('accounts:'):
                offset = max(0, int(action.split(':')[1]))
                accounts = runtime.store.admin_accounts()
                keyboard = InlineKeyboardMarkup(row_width=1)
                for a in accounts[offset:offset + 8]:
                    state = 'исключён' if a['disabled'] else ('занят' if a['order_id'] else a['state'])
                    keyboard.add(InlineKeyboardButton(f"#{a['id']} {a['email']} — {state}",
                                                     callback_data=prefix + f"account:{a['id']}"))
                if offset:
                    keyboard.add(InlineKeyboardButton('Назад', callback_data=prefix + f'accounts:{max(0, offset-8)}'))
                if offset + 8 < len(accounts):
                    keyboard.add(InlineKeyboardButton('Далее', callback_data=prefix + f'accounts:{offset+8}'))
                say(chat_id, 'Аккаунты' if accounts else 'Аккаунтов пока нет.', keyboard)
            elif action.startswith(('account:', 'disable:', 'check:')):
                account_id = int(action.split(':')[1])
                a = next(x for x in runtime.store.admin_accounts() if x['id'] == account_id)
                if action.startswith('disable:'):
                    runtime.store.set_disabled(account_id, not a['disabled'])
                    say(chat_id, 'Доступность для новых выдач изменена. Текущая аренда продолжается.')
                elif action.startswith('check:'):
                    account = next(x for x in runtime.store.accounts() if x['id'] == account_id)
                    items, _ = runtime.mail.Client(account).pickup()
                    senders = sorted({parseaddr(str(item.get('sender', '')))[1] for item in items})
                    senders = [s for s in senders if s][:10]
                    detail = '\nОтправители писем: ' + ', '.join(escape(s) for s in senders) if senders else ''
                    say(chat_id, f'Remail ответил. Писем: {len(items)}. Коды и токены скрыты.' + detail)
                else:
                    keyboard = InlineKeyboardMarkup()
                    keyboard.add(InlineKeyboardButton('Проверить Remail', callback_data=prefix + f'check:{account_id}'))
                    keyboard.add(InlineKeyboardButton('Вернуть в пул' if a['disabled'] else 'Исключить из пула',
                                                       callback_data=prefix + f'disable:{account_id}'))
                    say(chat_id, f"<b>#{a['id']}</b> {escape(a['email'])}\nСостояние: {escape(a['state'])}"
                        f"\nЛимиты 5 ч / 7 дней: {a['five']} / {a['seven']} %"
                        f"\nЗаказ: {escape(a['order_id'] or 'нет')}\nИсключён из новых выдач: {'да' if a['disabled'] else 'нет'}", keyboard)
            elif action == 'rentals':
                rows = runtime.store.recent_rentals()
                text = '\n'.join(f"{escape(r['order_id'])}: аккаунт #{r['account_id']}, {escape(r['state'])}, "
                                 f"окончание {runtime.core.end_time(r['expires'])}" for r in rows)
                say(chat_id, text or 'Аренд пока нет.')
        except Exception:
            say(chat_id, 'Операция не выполнена. Проверьте данные или доступ к Remail; секреты не выводятся.')

    def input_message(m):
        if not permitted(m.from_user.id, m.chat):
            return
        state = tg.get_state(m.chat.id, m.from_user.id)
        if not state or not state['state'].startswith(state_prefix):
            return
        stage = state['state'][len(state_prefix):]
        value = (m.text or '').strip()
        if stage == 'pickup':
            links = [e.url for e in (m.entities or []) if e.type == 'text_link' and e.url]
            if len(links) == 1:
                value = links[0]
            elif len(links) > 1:
                value = ''  # Ask for exactly one URL; never guess which mailbox is intended.
            try:
                bot.delete_message(m.chat.id, m.id)
            except Exception:
                pass
        try:
            if stage == 'email':
                if not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', value):
                    raise ValueError('Invalid email')
                result = say(m.chat.id, 'Вставьте персональную ссылку Remail целиком. Сообщение со ссылкой будет удалено по возможности.')
                tg.set_state(m.chat.id, result.id, m.from_user.id, state_prefix + 'pickup', {'email': value})
                return
            if stage == 'pickup':
                runtime.store.add(state['data']['email'], value)
            elif stage == 'preview':
                seconds = duration(value, 1, runtime.config['rules'])
                say(m.chat.id, ('Распознано: ' + runtime.core.format_duration(seconds) + '. Бонус за отзыв не включён.')
                    if seconds is not None else 'Подходящего правила нет. Откройте «Лоты и сроки».')
                tg.clear_state(m.chat.id, m.from_user.id)
                return
            elif stage == 'new_rule_title':
                if not 1 <= len(value) <= 1000:
                    raise ValueError('Invalid title')
                result = say(m.chat.id, 'Теперь введите срок: например, 30 мин или 1 час.')
                tg.set_state(m.chat.id, result.id, m.from_user.id, state_prefix + 'new_rule_minutes', {'title': value})
                return
            else:
                with runtime.lock:
                    if stage == 'senders':
                        senders = [x.strip() for x in value.split(',')]
                        if not all(re.fullmatch(r'[^\s@,<>]+@[^\s@,<>]+\.[^\s@,<>]+', x) for x in senders):
                            raise ValueError('Invalid sender')
                        runtime.config['mailbox']['allowed_senders'] = senders
                    elif stage in ('rule_title', 'rule_minutes'):
                        index = state['data']['index']
                        if runtime.config['rules'][index] != state['data']['before']:
                            raise ValueError('Settings changed; reopen editor')
                        rule = copy.deepcopy(runtime.config['rules'][index])
                        if stage == 'rule_title':
                            if not 1 <= len(value) <= 1000:
                                raise ValueError('Invalid title')
                            rule.update(label=value, pattern=rules_module.literal_pattern(value))
                            rule.pop('check_paid_term', None)
                        else:
                            minutes = rules_module.parse_minutes(value)
                            rule.pop('hours', None)
                            rule.pop('seconds', None)
                            rule['minutes'] = minutes
                        runtime.config['rules'][index] = rule
                    elif stage == 'new_rule_minutes':
                        if len(runtime.config['rules']) >= 20:
                            raise ValueError('Too many rules')
                        title = state['data']['title']
                        runtime.config['rules'].append({'label': title, 'pattern': rules_module.literal_pattern(title),
                                                       'minutes': rules_module.parse_minutes(value), 'quantity_is_duration': True})
                    else:
                        return
                    runtime.save_config()
            tg.clear_state(m.chat.id, m.from_user.id)
            say(m.chat.id, 'Сохранено. Для применения настроек Claude-адаптера перезапустите Cardinal.'
                if stage == 'senders' else 'Сохранено.')
            menu(m.chat.id)
        except runtime.mail.MailError as exc:
            explanations = {
                'pickup_host': 'Поддерживаются ссылки remail.best и remail.aishop6.com.',
                'pickup_email': 'Почта в ссылке не совпадает с введённой. Начните заново через /claude_rental или отправьте ссылку для этой почты.',
                'pickup_token': 'В ссылке отсутствует token или он указан несколько раз. Скопируйте персональную ссылку целиком.',
                'pickup_format': 'Отправьте одну полную ссылку HTTPS на страницу /pickup.',
            }
            say(m.chat.id, explanations.get(exc.code, 'Не удалось проверить ссылку Remail. Повторите ввод.'))
        except sqlite3.IntegrityError:
            say(m.chat.id, 'Эта почта уже добавлена. Откройте «Аккаунты» через /claude_rental.')
        except Exception:
            say(m.chat.id, 'Не удалось обработать данные: проверьте формат, единственное правило лота и срок (30 мин или 1 час). Повторите ввод или /claude_rental.')

    cardinal.add_telegram_commands(UUID, [('claude_rental', 'Аренда Claude', True)])
    tg.msg_handler(command, commands=['claude_rental'])
    tg.msg_handler(input_message, func=lambda m: bool((s := tg.get_state(m.chat.id, m.from_user.id))
                                                     and s['state'].startswith(state_prefix)), content_types=['text'])
    tg.cbq_handler(callback, lambda c: c.data.startswith(prefix) or
                   c.data.startswith(f'{CBT.PLUGIN_SETTINGS}:{UUID}:'))


def init(cardinal, *args):
    global _runtime
    if _runtime is not None:
        return
    try:
        _runtime = Runtime(cardinal, os.environ.get('CLAUDE_RENTAL_CONFIG', 'storage/claude_rental/config.json'))
        register_panel(_runtime)
    except Exception:
        log.error('Claude Rental: initialization failed; check local configuration')


def start(cardinal, *args):
    if _runtime:
        _runtime.start()


def stop(cardinal, *args):
    if _runtime:
        _runtime.shutdown()


def new_order(cardinal, event, *args):
    if _runtime:
        try:
            _runtime.enqueue(event.order)
        except Exception:
            _runtime.last_error = 'Заказ не поставлен в очередь: проверьте правило лота и состояние очереди.'
            log.error('Claude Rental: order could not be queued')


def review_event(cardinal, event, *args):
    if not _runtime:
        return
    from FunPayAPI.common.enums import MessageTypes
    obj = getattr(event, 'message', None)
    if obj is not None:
        if cardinal.old_mode_enabled:
            return
        kind, mine = obj.type, obj.i_am_buyer
    else:
        if not cardinal.old_mode_enabled:
            return
        obj = getattr(event, 'chat', None)
        if obj is None:
            return
        kind = obj.last_message_type
        mine = f' {cardinal.account.username} ' in str(obj)
    if kind in (MessageTypes.NEW_FEEDBACK, MessageTypes.FEEDBACK_CHANGED) and not mine:
        _runtime.queue_review('object', obj)


def order_changed(cardinal, event, *args):
    if _runtime and event.order.status.name in ('PAID', 'CLOSED'):
        _runtime.queue_review('id', str(event.order.id))


BIND_TO_DELETE = stop
BIND_TO_PRE_INIT = [init]
BIND_TO_POST_START = [start]
BIND_TO_PRE_STOP = [stop]
BIND_TO_NEW_ORDER = [new_order]
BIND_TO_NEW_MESSAGE = [review_event]
BIND_TO_LAST_CHAT_MESSAGE_CHANGED = [review_event]
BIND_TO_ORDER_STATUS_CHANGED = [order_changed]
